# align the independent references to the documented global-label merge
for path in ('fuzz.py', 'fuzz2.py'):
    src = open(path).read()
    old = """            segs = []
            for j in range(len(chunks)):
                low = max(r['start'], bounds[j])
                high = min(r['end'], bounds[j + 1])
                if high > low:
                    if segs and segs[-1][0] == labels[j]:
                        segs[-1][1] += high - low
                    else:
                        segs.append([labels[j], high - low])"""
    new = """            segs = []
            counts = {}
            for j in range(len(chunks)):
                low = max(r['start'], bounds[j])
                high = min(r['end'], bounds[j + 1])
                if high > low:
                    if labels[j] not in counts:
                        counts[labels[j]] = 0
                        segs.append([labels[j], 0])
                    counts[labels[j]] += high - low
            for entry in segs:
                entry[1] = counts[entry[0]]"""
    assert old in src, path
    src = src.replace(old, new)
    open(path, 'w').write(src)
print('aligned')
